   // Tampilkan lebih banyak kab/kota agar area panel terisi lebih proporsional.
   const kabMainData=kabData.slice(0,25);
   const kabEndLabelsPlugin={id:"kabEndLabels",afterDatasetsDraw(chart){const meta=chart.getDatasetMeta(0),ctx=chart.ctx;ctx.save();ctx.font="700 10px Segoe UI,Arial";ctx.fillStyle="#334155";ctx.textAlign="left";ctx.textBaseline="middle";meta.data.forEach((bar,i)=>{const val=chart.data.datasets[0].data[i]; if(val==null)return; ctx.fillText(String(val),bar.x+6,bar.y);});ctx.restore();}};
   if(kabChart)kabChart.destroy();
