(function(){
  function parseYearValue(v){
    if(v===null||v===undefined||v==='') return NaN;
    const s=String(v).trim();
    const n=Number(s); if(Number.isFinite(n)&&n>1900&&n<2200) return Math.round(n);
    const m=s.match(/(?:^|\D)((?:19|20|21)\d{2})(?:\D|$)/);
    return m?Number(m[1]):NaN;
  }

  // Force a robust LIDI yearly chart using INPUT DATA -> Tahun Pembentukan.
  window.renderLidiYearChart=function(attempt=0){
    const canvas=$("lidiYearChart"); if(!canvas) return;
    const box=canvas.parentElement;
    const rawRows=Array.isArray(LIDI_DATA)?LIDI_DATA:[];
    const years=[...new Set(rawRows.map(x=>parseYearValue(x.tahun)).filter(y=>Number.isFinite(y)))].sort((a,b)=>a-b);
    const counts=years.map(y=>rawRows.filter(x=>parseYearValue(x.tahun)===y).length);
    if(lidiYearChart){try{lidiYearChart.destroy();}catch(_){ }lidiYearChart=null;}
    if(box) box.querySelectorAll('.lidi-chart-fallback').forEach(el=>el.remove());
    if(!years.length){
      if(box)box.insertAdjacentHTML('beforeend','<div class="lidi-chart-fallback emptychart">Data Tahun Pembentukan pada INPUT DATA belum ditemukan.</div>');
      return;
    }
    const visible = canvas.offsetParent !== null && canvas.clientWidth > 20 && canvas.clientHeight > 20;
    if(!visible && attempt < 20){ setTimeout(()=>window.renderLidiYearChart(attempt+1),250); return; }
    const drawChart=()=>{
      if(typeof Chart==='undefined'){
        if(attempt<20){setTimeout(()=>window.renderLidiYearChart(attempt+1),300);return;}
        renderLidiYearFallback(); return;
      }
      try{
        canvas.style.display='block';
        const plugin={id:'lidiYearTotalsV55',afterDatasetsDraw(chart){const ctx=chart.ctx;const meta=chart.getDatasetMeta(0);ctx.save();ctx.font='700 11px Segoe UI,Arial';ctx.fillStyle='#334155';ctx.textAlign='center';ctx.textBaseline='bottom';meta.data.forEach((bar,i)=>{const v=Number(chart.data.datasets[0].data[i])||0;if(v)ctx.fillText(String(v),bar.x,bar.y-7);});ctx.restore();}};
        lidiYearChart=new Chart(canvas,{type:'bar',data:{labels:years,datasets:[{label:'Jumlah Unit LIDI',data:counts,backgroundColor:'#2F80ED',borderRadius:5,maxBarThickness:56}]},plugins:[plugin],options:{responsive:true,maintainAspectRatio:false,layout:{padding:{top:20,left:10,right:10,bottom:4}},plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>`${c.raw} unit LIDI`}}},scales:{x:{title:{display:true,text:'Tahun'},ticks:{autoSkip:false,font:{size:10}}},y:{beginAtZero:true,ticks:{precision:0},title:{display:true,text:'Jumlah Unit'}}}}});
        setTimeout(()=>{try{lidiYearChart.resize();lidiYearChart.update('none');}catch(_){ }},120);
      }catch(err){
        renderLidiYearFallback();
      }
    };
    function renderLidiYearFallback(){
      if(!box) return;
      box.querySelectorAll('.lidi-chart-fallback').forEach(el=>el.remove());
      const max=Math.max(...counts,1);
      const bars=years.map((y,i)=>{const h=Math.max(8,Math.round(counts[i]/max*100));return `<div class="lidi-fallback-item"><div class="lidi-fallback-value">${counts[i]}</div><div class="lidi-fallback-bar" style="height:${h}%"></div><div class="lidi-fallback-year">${y}</div></div>`}).join('');
      box.insertAdjacentHTML('beforeend',`<div class="lidi-chart-fallback"><div class="lidi-fallback-bars">${bars}</div></div>`);
    }
    requestAnimationFrame(()=>requestAnimationFrame(drawChart));
  };

  // Keep the chart responsive when the LIDI page is opened after being hidden.
  const _renderLidi=window.renderLidi;
  window.renderLidi=function(){if(typeof _renderLidi==='function')_renderLidi();[80,250,600].forEach(ms=>setTimeout(window.renderLidiYearChart,ms));};
  if(window.ResizeObserver){ const ro=new ResizeObserver(()=>{ if($("lidi")?.classList.contains("active")){ window.renderLidiYearChart?.(); } }); const lb=$("lidiYearChart"); if(lb) ro.observe(lb.parentElement); }
  window.addEventListener('load',()=>{[300,1000,1800].forEach(ms=>setTimeout(()=>window.renderLidiYearChart?.(),ms));});

  // Independent KRB/RPB/RPKB detail modal.
  let dokDetailCharts={};
  const detailLabelPlugin={id:'dokDetailLabelsV53',afterDatasetsDraw(chart){const meta=chart.getDatasetMeta(0),data=chart.data.datasets[0]?.data||[],total=data.reduce((a,b)=>a+(Number(b)||0),0),ctx=chart.ctx;ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='700 12px Segoe UI,Arial';meta.data.forEach((arc,i)=>{const v=Number(data[i])||0;if(!v)return;const p=total?v/total*100:0,pos=arc.getCenterPoint();ctx.strokeStyle='rgba(15,23,42,.35)';ctx.lineWidth=2;ctx.fillStyle='#fff';ctx.strokeText(String(v),pos.x,pos.y-7);ctx.fillText(String(v),pos.x,pos.y-7);ctx.strokeText(p.toFixed(1)+'%',pos.x,pos.y+8);ctx.fillText(p.toFixed(1)+'%',pos.x,pos.y+8)});ctx.restore();}};
  function showDokPlanningDetail(){
    const m=$("dokPlanningDetailModal"); if(!m)return; m.classList.add('show'); m.style.display='flex';
    const base=docGlobalRows(); const types=['KRB','RPB','RPKB'];
    types.forEach(type=>{const id='dokDetail'+type;const c=$(id);if(!c)return;if(dokDetailCharts[id])dokDetailCharts[id].destroy();const active=base.filter(r=>String(r.jenis).trim().toUpperCase()===type&&docStatusKey(r.status)==='ACTIVE').length;const inactive=base.filter(r=>String(r.jenis).trim().toUpperCase()===type&&docStatusKey(r.status)==='INACTIVE').length;dokDetailCharts[id]=new Chart(c,{type:'doughnut',data:{labels:['AKTIF','TIDAK AKTIF'],datasets:[{data:[active,inactive],backgroundColor:['#27AE60','#F2C94C'],borderWidth:1}]},plugins:[detailLabelPlugin],options:{responsive:true,maintainAspectRatio:false,cutout:'58%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true,boxWidth:10,font:{size:10}}},tooltip:{callbacks:{label:ctx=>{const t=ctx.dataset.data.reduce((a,b)=>a+b,0),v=Number(ctx.raw)||0,p=t?v/t*100:0;return `${ctx.label}: ${v} (${p.toFixed(1)}%)`;}}}}}});});
  }
  function closeDokPlanningDetail(){const m=$("dokPlanningDetailModal");if(m){m.classList.remove('show');m.style.display='none';}Object.values(dokDetailCharts).forEach(c=>{try{c.destroy()}catch(_){}});dokDetailCharts={};}
  window.showDokPlanningDetail=showDokPlanningDetail;window.closeDokPlanningDetail=closeDokPlanningDetail;

  // Independent document status map below the table.
  let dokStatusMap=null,dokStatusLayer=null,dokStatusLabelLayer=null,dokStatusType='KRB',dokStatusGeo=null;
  function mapDocKabKey(v){let k=kabKey(v);if(k==='MAGELANG')return 'KOTA MAGELANG';return k;}
  function docMapRows(type){
    const out={};
    (Array.isArray(DOC_DATA)?DOC_DATA:[]).forEach(r=>{const t=String(r.jenis||'').trim().toUpperCase();if(t!==type)return;const k=mapDocKabKey(r.kab);if(!k)return;(out[k] ||= []).push(r);});
    return out;
  }
  function statusForDocRows(rows){
    if(!rows||!rows.length)return {key:'NONE',label:'TIDAK ADA',dari:'',sampai:''};
    const active=rows.find(r=>docStatusKey(r.status)==='ACTIVE');
    const inactive=rows.find(r=>docStatusKey(r.status)==='INACTIVE');
    const pick=active||inactive||rows[0];
    const key=active?'ACTIVE':inactive?'INACTIVE':'NONE';
    return {key,label:key==='ACTIVE'?'AKTIF':key==='INACTIVE'?'TIDAK AKTIF':'TIDAK ADA',dari:pick?.dari||'',sampai:pick?.sampai||''};
  }
  function docMapStyle(key,isJateng){if(!isJateng)return {fillColor:'#bdbdbd',weight:1.4,color:'#fff',fillOpacity:.58};const c=key==='ACTIVE'?'#27AE60':key==='INACTIVE'?'#F2C94C':'#D73027';return {fillColor:c,weight:1.5,color:'#fff',fillOpacity:.72};}
  function updateDokStatusMap(){
    if(!dokStatusLayer)return;
    const byKab=docMapRows(dokStatusType);
    const categories={ACTIVE:new Set(),INACTIVE:new Set(),NONE:new Set()};
    const labelOverrides={
      "CILACAP":[-7.512,108.904],
      "JEPARA":[-6.59,110.67]
    };
    if(dokStatusLabelLayer){dokStatusLabelLayer.clearLayers();}
    dokStatusLayer.eachLayer(layer=>{
      const p=layer.feature?.properties||{};
      const nama=p.WADMKK||p.nama_kabupaten||p.namobj||p.NAMOBJ||'';
      const kode=String(p.KDPKAB||p.kdp_kab||p.KD_PUM||p.kdpum||'').replace(/\s/g,'');
      const isMag=kode==='33.71'||kabKey(nama)==='KOTA MAGELANG';
      const isJateng=String(p.WADMPR||p.provinsi||p.WADMPRN||'').trim().toUpperCase()==='JAWA TENGAH'||kode.startsWith('33.')||isMag;
      const keyName=mapDocKabKey(nama);
      const info=isJateng?statusForDocRows(byKab[keyName]):null;
      layer.setStyle(docMapStyle(info?.key||'NONE',isJateng));
      layer.off('click');
      layer.on('click',()=>{
        if(!isJateng){layer.bindPopup(`<b>${esc(nama)}</b><br><span style="color:#666">Wilayah di luar Jawa Tengah</span>`).openPopup();return;}
        const tahun=info.dari&&info.sampai?`Berlaku: <b>${esc(info.dari)}–${esc(info.sampai)}</b>`:(info.dari?`Mulai: <b>${info.dari}</b>`:'');
        layer.bindPopup(`<div style="min-width:190px"><b style="font-size:15px">${esc(nama)}</b><br>Status ${dokStatusType}: <b>${esc(info.label)}</b>${tahun?`<br>${tahun}`:''}</div>`).openPopup();
      });
      if(isJateng){
        const bucket=info?.key||'NONE';
        if(categories[bucket]) categories[bucket].add(keyName);
        if(dokStatusLabelLayer&&nama && ![...dokStatusLabelLayer.getLayers()].some(l=>n(l.options?.__dokLabelKey||"")===n(keyName))){
          const center=labelOverrides[keyName]?L.latLng(labelOverrides[keyName][0],labelOverrides[keyName][1]):layer.getBounds().getCenter();
          L.marker(center,{icon:L.divIcon({className:'kabupaten-label-wrap',html:`<span class="kabupaten-label dok-kabupaten-label">${esc(nama)}</span>`,iconSize:null,iconAnchor:[0,0],__dokLabelKey:keyName}),interactive:false,keyboard:false,zIndexOffset:900}).addTo(dokStatusLabelLayer);
        }
      }
    });
    Object.keys(categories).forEach(k=>categories[k]=[...categories[k]].sort((a,b)=>a.localeCompare(b,'id')));
    const put=(id,arr)=>{const el=$(id);if(!el)return;el.innerHTML=arr.length?arr.map(n=>`<button type="button" data-doc-map-kab="${esc(n)}">${esc(n)}</button>`).join(''):'<div class="dok-status-list-empty">—</div>';};
    put('dokStatusListActive',categories.ACTIVE); put('dokStatusListInactive',categories.INACTIVE); put('dokStatusListNone',categories.NONE);
    const legend=$("dokStatusMapLegend"); if(legend)legend.innerHTML='<div class="map-legend-title">Status Dokumen</div><div class="map-legend-items"><span><i style="background:#27AE60"></i>Aktif</span><span><i style="background:#F2C94C"></i>Tidak Aktif</span><span><i style="background:#D73027"></i>Tidak Ada</span><span><i style="background:#bdbdbd"></i>Wilayah di luar Jawa Tengah</span></div>';
  }
  function initDokStatusMap(){
    const el=$("dokStatusMap");if(!el||typeof L==='undefined')return;
    if(!dokStatusMap){
      dokStatusMap=L.map(el,{zoomControl:true,scrollWheelZoom:true}).setView([-7.2,110.2],8);
      dokStatusLabelLayer=L.layerGroup().addTo(dokStatusMap);
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(dokStatusMap);
      try{dokStatusGeo=window.JATENG_KAB_GEOJSON||null;}catch(_){dokStatusGeo=null;}
      const finish=(geo)=>{
        dokStatusGeo=geo;
        if(dokStatusLayer)dokStatusLayer.remove();
        dokStatusLayer=L.geoJSON(geo,{style:{fillColor:'#bdbdbd',weight:1.4,color:'#fff',fillOpacity:.6}}).addTo(dokStatusMap);
        updateDokStatusMap();
        const jt=[];
        dokStatusLayer.eachLayer(layer=>{
          const p=layer.feature?.properties||{};
          const nama=p.WADMKK||p.nama_kabupaten||p.namobj||p.NAMOBJ||'';
          const kode=String(p.KDPKAB||p.kdp_kab||p.KD_PUM||p.kdpum||'').replace(/\s/g,'');
          const isMag=kode==='33.71'||kabKey(nama)==='KOTA MAGELANG';
          const isJateng=String(p.WADMPR||p.provinsi||p.WADMPRN||'').trim().toUpperCase()==='JAWA TENGAH'||kode.startsWith('33.')||isMag;
          if(isJateng) jt.push(layer);
        });
        if(jt.length){const g=L.featureGroup(jt);dokStatusMap.fitBounds(g.getBounds(),{padding:[8,8],maxZoom:9});}
        else dokStatusMap.setView([-7.2,110.2],8);
        setTimeout(()=>dokStatusMap.invalidateSize(),100);
      };
      if(dokStatusGeo)finish(dokStatusGeo);else fetch('jateng-kab.geojson').then(r=>r.json()).then(finish).catch(()=>{});
    }else{setTimeout(()=>dokStatusMap.invalidateSize(),100);updateDokStatusMap();}
  }
  window.initDokStatusMap=initDokStatusMap;window.updateDokStatusMap=updateDokStatusMap;
  const oldRenderDok=window.renderDokumen;
  window.renderDokumen=function(){if(typeof oldRenderDok==='function')oldRenderDok();[250,800,1600,2800].forEach(ms=>setTimeout(()=>{initDokStatusMap();if(dokStatusMap)dokStatusMap.invalidateSize();updateDokStatusMap();},ms));};
  let dokRenkonDetailChart=null, dokRenkonDetailSort='count';
  function showDokRenkonDetail(){
    const m=$("dokRenkonDetailModal");if(!m)return;
    const rows=docGlobalRows();
    let pairs=[...new Set(rows.map(r=>String(r.jenis||'').trim().toUpperCase()).filter(x=>x.startsWith('RENKON')))];
    const countsMap=new Map(pairs.map(x=>[x,rows.filter(r=>String(r.jenis||'').trim().toUpperCase()===x).length]));
    if(dokRenkonDetailSort==='alpha') pairs.sort((a,b)=>a.localeCompare(b,'id'));
    else if(dokRenkonDetailSort==='countAsc') pairs.sort((a,b)=>(countsMap.get(a)||0)-(countsMap.get(b)||0)||a.localeCompare(b,'id'));
    else pairs.sort((a,b)=>(countsMap.get(b)||0)-(countsMap.get(a)||0)||a.localeCompare(b,'id'));
    const labels=pairs.map(x=>x.replace(/^RENKON\s+/i,''));
    const data=pairs.map(x=>countsMap.get(x)||0);
    m.classList.add('show');m.style.display='flex';
    const c=$("dokRenkonDetailChart"); if(!c||typeof Chart==='undefined')return;
    if(dokRenkonDetailChart){try{dokRenkonDetailChart.destroy()}catch(_){} }
    const totalPlugin={id:'dokRenkonTotalsV55',afterDatasetsDraw(chart){const meta=chart.getDatasetMeta(0),ctx=chart.ctx;ctx.save();ctx.font='700 11px Segoe UI,Arial';ctx.textAlign='center';ctx.textBaseline='bottom';ctx.fillStyle='#334155';meta.data.forEach((bar,i)=>{const v=Number(chart.data.datasets[0].data[i])||0;if(v)ctx.fillText(String(v),bar.x,bar.y-7)});ctx.restore();}};
    dokRenkonDetailChart=new Chart(c,{type:'bar',data:{labels,datasets:[{label:'Jumlah Dokumen',data,backgroundColor:'#2F80ED',borderRadius:5,maxBarThickness:56}]},plugins:[totalPlugin],options:{responsive:true,maintainAspectRatio:false,layout:{padding:{top:20,left:10,right:10,bottom:6}},plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>`${ctx.raw} dokumen`}}},scales:{x:{ticks:{maxRotation:35,minRotation:35,autoSkip:false,font:{size:10}}},y:{beginAtZero:true,ticks:{precision:0}}}}});
  }
  function closeDokRenkonDetail(){const m=$("dokRenkonDetailModal");if(m){m.classList.remove('show');m.style.display='none';}if(dokRenkonDetailChart){try{dokRenkonDetailChart.destroy()}catch(_){}dokRenkonDetailChart=null;}}
  window.showDokRenkonDetail=showDokRenkonDetail;window.closeDokRenkonDetail=closeDokRenkonDetail;
  document.addEventListener('click',e=>{
    if(e.target.closest?.('#dokRenkonDetailBtn'))showDokRenkonDetail();
    if(e.target.closest?.('#closeDokRenkonDetail')||e.target.id==='dokRenkonDetailModal')closeDokRenkonDetail();
    const b=e.target.closest?.('[data-doc-map-kab]'); if(b&&dokStatusMap){ const name=b.getAttribute('data-doc-map-kab'); dokStatusLayer?.eachLayer(layer=>{const p=layer.feature?.properties||{},n=mapDocKabKey(p.WADMKK||p.nama_kabupaten||p.namobj||p.NAMOBJ||'');if(n===name){dokStatusMap.fitBounds(layer.getBounds(),{padding:[40,40],maxZoom:9});layer.fire('click');}}); }
  });
  window.addEventListener('resize',()=>{try{dokRenkonDetailChart?.resize();}catch(_){}});
  document.addEventListener('change',e=>{if(e.target?.id==='dokStatusMapType'){dokStatusType=e.target.value||'KRB';updateDokStatusMap();}});
document.addEventListener('click',e=>{
  const ds=e.target.closest?.('[data-destana-sort]'); if(ds){const key=Number(ds.dataset.destanaSort); if(destanaSortKey===key)destanaSortDir=destanaSortDir==='asc'?'desc':'asc'; else{destanaSortKey=key;destanaSortDir='asc';} table(cols()); return;}
  const es=e.target.closest?.('[data-ews-sort]'); if(es){const key=Number(es.dataset.ewsSort); if(ewsSortKey===key)ewsSortDir=ewsSortDir==='asc'?'desc':'asc'; else{ewsSortKey=key;ewsSortDir='asc';} ewsCurrentPage=1;renderEWSTable(ewsCols()); return;}
});
document.addEventListener('change',e=>{if(e.target?.id==='dokRenkonSortMain'){updateDokSummaryAndCharts();}});
const destanaPageSizeEl=$("destanaPageSize");
if(destanaPageSizeEl){destanaPageSizeEl.addEventListener('change',()=>{rowsPerPage=Number(destanaPageSizeEl.value)||10;currentPage=1;table(cols());});}

  document.addEventListener('change',e=>{if(e.target?.id==='dokRenkonDetailSort'){dokRenkonDetailSort=e.target.value||'count';showDokRenkonDetail();}});
  document.addEventListener('click',e=>{if(e.target.closest?.('#dokPlanningDetailBtn'))showDokPlanningDetail();if(e.target.closest?.('#closeDokPlanningDetail'))closeDokPlanningDetail();});
  window.addEventListener('resize',()=>{try{dokStatusMap?.invalidateSize();}catch(_){}});
})();
